head.script:
scwin.screenId = "jldfil16201";

///////// 1. 변수 및 선언 영역 /////////

scwin.candidateValSeq = undefined;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb1", fn: function () { return String(dma_poll.get("questStrtDd")) + " ~ " + String(dma_poll.get("questEndDd")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — jldfil16201: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.insQuest = undefined; try { scwin.insQuest = /* sdd-asis-lifecycle:begin insQuest — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Quest((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "quesCnt" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("quesCnt"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "quesCnt" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("quesCnt")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "quesCnt" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("quesCnt"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "quesCnt" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("quesCnt"))))))/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil16201' }); }

scwin.Quest = Quest;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil16201.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_RegisterPoll_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_RegisterPoll_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_RegisterPoll_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.registerPoll('' + dma_poll.get("questNo") + '',1)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16201.btn_RegisterPoll_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_RegisterPoll
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_RegisterPoll = async function () {
    const sbmOptions = {
        id: "tx_fn_RegisterPoll",
        method: "post",
        action: "/support/poll.do",
        ref: "dma_RegisterPollReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16201.tx_fn_RegisterPoll" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

function Quest(_quesCnt) {
    /* sdd-asis-lifecycle:begin Quest — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    this.quesCnt = _quesCnt;
    this.quesObj = [];
    /* sdd-asis-lifecycle:end */
}

/**
 * @method
 * @name scwin.Ques
 * @author Inswave
 * @date 2026. 09. 29
 * @param _quesNo _quesTpCd _ansChoicCnt _upQuesNo _respnsMandtryNoContn _respnsMandtryYn
 * @returns
 * @hidden N
*/
scwin.Ques = function (_quesNo, _quesTpCd, _ansChoicCnt, _upQuesNo, _respnsMandtryNoContn, _respnsMandtryYn) {
    /* sdd-asis-lifecycle:begin Ques — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    this.quesNo = _quesNo;
    this.quesTpCd = _quesTpCd;
    this.ansChoicCnt = _ansChoicCnt;
    this.upQuesNo = _upQuesNo;
    this.respnsMandtryNoContn = _respnsMandtryNoContn;
    this.respnsMandtryYn = _respnsMandtryYn;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.registerPoll
 * @author Inswave
 * @date 2026. 09. 29
 * @param _questNo _questProgStatCd
 * @returns
 * @hidden N
*/
scwin.registerPoll = async function (_questNo, _questProgStatCd) {
    /* sdd-asis-lifecycle:begin fn_RegisterPoll — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.pollListForm || { elements: [] });
    $c.util.getComponent('dma_RegisterPollReq').set('questNo', _questNo);
    $c.util.getComponent('dma_RegisterPollReq').set('questProgStatCd', _questProgStatCd);
    $c.util.getComponent('dma_RegisterPollReq').set('method', 'registerPollForm');
    frm.action = 'poll.do';
    { const nr = await scwin.tx_fn_RegisterPoll(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil16200/jldfil16200.xml", { "questNo": _questNo, "questProgStatCd": _questProgStatCd, "method": 'registerPollForm' }); } };
    /* sdd-asis-lifecycle:end */
};
